def transform(grid):
    row = grid[0]
    n = len(row)
    center = row.index(2)
    out = [[0] * n for _ in range(n)]

    for r in range(n):
        for c in (center - r, center + r):
            if 0 <= c < n:
                out[r][c] = 2

        for c in range(n):
            if abs(c - center) <= r and (c - r - center) % 4 == 0 and out[r][c] == 0:
                out[r][c] = 1

    return out
